import json,pathlib
root=pathlib.Path(__file__).resolve().parents[1]/'site'/'policy-view'
d=json.loads((root/'policy-data.json').read_text());P={p['id']:p for p in d['policies']}; graphs=[]
def graph(pid,period,group,comparator):
 p=P[pid]; g={'policyId':pid,'title':p['title'],'mode':'retrospective','review':{'reviewer_type':'AI','human_approved':False,'status':'curated_source_checked_research_draft'},'geography':p['jurisdiction'],'horizon':period,'affectedGroups':[group],'evidenceCutoff':d['asOf'],'comparator':comparator,'assumptions':['Direction applies to the named outcome/proxy and comparator, not demonstrated attainment of the whole slice.'],'costs':p['tradeoffs'],'validation':['Audit source design, denominators and dates; do not transfer this estimate to another place or group without an explicit transportability argument.','Measure baseline, intervention exposure, distribution and counterfactual; retain outcome units and uncertainty.'],'edges':[]};graphs.append(g);return g

def edge(g,s,direction,evidence,link,outcome,path,sources=(0,),magnitude=None,limit='',condition=''):
 p=P[g['policyId']];g['edges'].append({'id':g['policyId']+'-'+str(len(g['edges'])+1),'slice':s,'provenance':'curatedReview','direction':direction,'evidence':evidence,'link':link,'outcome':outcome,'pathId':g['policyId']+':'+path,'mechanism':p['mechanism'],'geography':g['geography'],'horizon':g['horizon'],'affectedGroups':g['affectedGroups'],'comparator':g['comparator'],'magnitude':magnitude,'sources':[{'title':p['sources'][i]['title'],'url':p['sources'][i].get('full_text',p['sources'][i]['url']),'locator':p['sources'][i].get('locator','See source and full case record')} for i in sources],'uncertainty':limit or p['caution'],'assumptions':[condition] if condition else (['Mechanism hypothesis only; the cited case does not identify this downstream outcome.'] if evidence=='inferred' else []),'validation':'Measure this outcome separately; do not add it to another outcome along the same causal path.'})
T='towardSafeJust'; A='away'; M='mixed'; U='unknown'; N='noDemonstratedChange'; Q='quasiExperimental'; O='observed'; I='inferred'; MD='modeled'
g=graph('nyc-universal-school-meals','School exposure 2010–2013, not 2017 rollout','NYC middle-school students, poor and non-poor','Within-student difference-in-differences under identifying assumptions')
edge(g,'food',T,Q,'direct','Lunch participation increases; food-security attainment was not measured.','meal-access',magnitude={'value':5.395,'unit':'percentage points','metric':'Lunch participation, poor students','uncertainty':'SE 1.389'})
edge(g,'education',T,Q,'indirect','Math and ELA test scores improve in the study; not evidence that every education outcome improves.','meal-access',magnitude={'value':0.032,'unit':'standard deviations','metric':'Math score, poor students','uncertainty':'SE 0.014; non-poor estimate 0.083 SD'},limit='Table 3; within-student design. Attendance effects are not uniformly beneficial. Do not count food and education as additive units of welfare.')
edge(g,'health',N,Q,'indirect','No demonstrated increase in overweight, obesity or average BMI; this is not proof of a zero health effect.','nutrition-weight',limit='Weight-outcome tests do not identify all nutritional or health effects; no synthetic health benefit assigned.')
edge(g,'social-equity',M,Q,'indirect','Both income groups benefit, but larger test-score gains for non-poor students do not establish a narrower income-group attainment gap.','meal-access',limit='Group estimates concern school outcomes, not overall equity or a causal stigma estimate.')
edge(g,'climate-change',U,I,'indirect','Net food-production, substitution and waste emissions are unmeasured.','meal-footprint',condition='Compare additional meals with displaced household meals, procurement and food waste.')

g=graph('sc-water-rationing','June–November 2014 vs the same months in 2013','Customers of Santa Cruz Water service area','Prior-year use; no untreated, weather-adjusted counterfactual')
edge(g,'freshwater-withdrawals',T,O,'direct','Reported water demand fell; sustainable yield and environmental flows were not established.','water-demand',magnitude={'value':-26,'unit':'percent average monthly use','metric':'Water savings vs prior-year months','uncertainty':'Administrative before–after; not necessarily volume-weighted seasonal total'})
edge(g,'water-sanitation',U,I,'indirect','Lower demand may protect supply reliability, but household access and adequacy were not evaluated.','water-demand',condition='Essential use remains affordable and reliable during drought.')
edge(g,'income-work',M,I,'indirect','Reduced consumption may lower volumetric bills; penalties and fixed-cost recovery can offset savings.','water-bills',sources=(0,2),limit='Fiscal/distributional mechanism, not a quantified household effect. Utility revenue pressure is not social welfare loss by itself.')
edge(g,'biodiversity-loss',U,I,'indirect','Aquatic habitat improvement is not demonstrated by household savings alone.','water-demand',condition='Saved withdrawals must translate into ecologically useful timing and streamflows.')

g=graph('nyc-right-to-counsel','Housing-court rollout 2016–2019','Tenants in cases in targeted ZIP codes; landlords and legal-service workers','Within-ZIP rollout with borough-by-month controls')
edge(g,'housing',T,Q,'direct','Reduced eviction probability across targeted housing-court cases.','legal-retention',magnitude={'value':-1.0,'unit':'percentage point','metric':'Reduced-form eviction probability','uncertainty':'Do not substitute the separate −8.4 pp IV effect'})
edge(g,'peace-justice',T,Q,'direct','Program expands tenant legal representation; access to counsel is a justice proxy, not all institutional trust.','legal-retention',limit='Rollout design and service-capacity constraints apply; this is not an additional eviction effect to sum.')
edge(g,'social-equity',M,O,'indirect','Potentially high-risk tenants gain, but service gaps and declining representation limit equitable access.','legal-access-gaps',sources=(1,),limit='Comptroller service trends are descriptive; no single net equity score.')
edge(g,'health',U,I,'indirect','Housing stability could protect health, but this study does not identify health outcomes.','legal-retention',condition='Avoided displacement changes exposure, stress and care continuity.')
edge(g,'income-work',M,Q,'indirect','Tenant stability and landlord delay have different incidence; adjudication length rises in the IV specification.','legal-delay',magnitude={'value':85,'unit':'days','metric':'Time to judgment, representation IV specification','uncertainty':'Not the reduced-form program effect or a monetized net cost'})

g=graph('sc-adu-reform','Annual permit series 2017–2024','Unincorporated Santa Cruz County property owners and potential occupants','Observed permits over time; no no-reform counterfactual')
edge(g,'housing',U,O,'direct','ADU permits increase, but completion, occupancy, affordability and displacement effects remain unknown.','adu-units',sources=(2,),magnitude={'value':103,'unit':'permits in 2024','metric':'ADU permits, vs 28 in 2017','uncertainty':'Includes one tiny home on wheels; permits are not homes occupied'})
edge(g,'land-conversion',T,I,'indirect','Infill could avoid land conversion relative to equivalent new housing on undeveloped land.','adu-land',condition='ADUs actually substitute for greenfield development rather than solely add construction.')
edge(g,'freshwater-withdrawals',A,I,'indirect','Additional occupied units may add local water demand relative to no additional occupancy.','adu-resource',condition='Net occupancy and demand rise; quantify efficiency and displaced demand elsewhere.')
edge(g,'climate-change',M,I,'indirect','Construction embodies emissions; compact locations may reduce travel relative to sprawl. Net effect is unmeasured.','adu-lifecycle',condition='Compare like-for-like residents, floor area, construction and travel over the full lifecycle.')
edge(g,'social-equity',M,I,'indirect','Property and finance access shape who can build; new units are not necessarily affordable to low-income renters.','adu-distribution',sources=(0,1),limit='Distributional mechanism supported by program barriers, not estimated rent or inequality effect.')

g=graph('nyc-clean-heat','2011 vs 2016 pollution; conversions 2012–2016','Residents of NYC census tracts; building owners and tenants','Adjusted spatial association, not untreated-city causal contrast')
edge(g,'air-pollution',T,O,'direct','More conversions are associated with lower ambient PM2.5.','clean-air',magnitude={'value':-0.12,'unit':'µg/m³ PM2.5 per 10 converted buildings','metric':'Census-tract conversion association','uncertainty':'95% CI −0.15 to −0.09; not citywide causal reduction'})
edge(g,'health',T,I,'indirect','Lower particulate exposure plausibly supports health; deaths or hospitalizations are not identified by this coefficient.','clean-air',condition='Exposure reduction reaches people and exposure-response relations transfer; no counted avoided deaths.')
edge(g,'climate-change',U,I,'indirect','Fuel substitution does not establish a lifecycle climate gain once upstream methane is included.','heat-fuel',condition='Account for fuel, efficiency, upstream leakage and no-conversion baseline.')
edge(g,'social-equity',M,O,'indirect','Financing and fuel-transition pathways differ across income groups; improvement is not uniform.','heat-equity',sources=(3,),limit='Residual Inequity study examines transition patterns, not a single aggregate equity effect.')
edge(g,'energy',M,I,'direct','Conversion capital and operating costs may improve or worsen affordability for different buildings and tenants.','heat-cost',sources=(1,),condition='Evaluate financing, pass-through, bill changes and reliability; do not assume savings.')

g=graph('sc-youth-cruz-free','Pilot from March 2023; survey May–August 2024','Surveyed Santa Cruz County teens; not a representative population sample','Retrospective reported behavior without untreated comparison')
edge(g,'networks',T,O,'direct','Some surveyed teens report beginning bus use during the pilot; this supports a mobility-access proxy.','youth-access',magnitude={'value':86,'unit':'of 280 respondents','metric':'Reported riding only after pilot','uncertainty':'31%; not a ridership growth rate or causal estimate'})
edge(g,'education',U,O,'indirect','Attendance impact could not be estimated because reported attendance had too little variation.','youth-access',limit='Research report pp14–15: 240 of 253 reported five or more days. This is an evidence gap, not evidence of no effect.')
edge(g,'income-work',T,I,'direct','Removal of fares can reduce out-of-pocket travel costs for would-be paying riders.','youth-fares',sources=(1,),condition='Relevant alternative would involve a paid fare; value of time and public funding remain separate.')
edge(g,'climate-change',U,I,'indirect','Net emissions depend on displaced car trips, induced trips, occupancy and service changes.','youth-mode',condition='Measure mode substitution and marginal service energy; new boardings are not avoided car journeys.')
edge(g,'social-equity',M,O,'indirect','Use varies with vehicle access, ethnicity and perceived safety; fare removal alone does not equalize access.','youth-access',limit='Survey associations are not causal subgroup treatment effects; rural/community representation gaps remain.')

g=graph('nyc-congestion-pricing','2025 rollout; sources reviewed through 26 October 2026','Cordon travelers, regional drivers, transit users and environmental-justice communities','Synthetic no-pricing speed counterfactual; separate air-quality comparisons')
edge(g,'networks',T,Q,'direct','Higher cordon speeds relative to a synthetic no-pricing counterfactual.','traffic-flow',magnitude={'value':11,'unit':'percent','metric':'Cordon-area speed','uncertainty':'Working-paper estimate; not equitable access or welfare magnitude'})
edge(g,'air-pollution',M,Q,'indirect','Pollution findings differ across endpoints, windows and methods; do not pool them.','traffic-air',sources=(1,2,4),limit='Official full-year evaluation found no statistically significant attributable CRZ change; other studies report reductions. Mixed here denotes conflicting evidence, not a measured zero.')
edge(g,'income-work',M,I,'direct','Drivers pay tolls; travelers may save time and transit users may benefit from funded investment.','toll-incidence',sources=(3,),limit='Tolls are transfers, not all resource cost. Distribution depends on travel, exemptions and revenue use.')
edge(g,'climate-change',U,I,'indirect','Speed changes alone do not identify net CO2 emissions or lifecycle climate impact.','traffic-flow',condition='Measure vehicle-kilometers, diversion, fleet, speeds and replacement transit energy.')
edge(g,'health',U,I,'indirect','Health effects require exposure and injury pathways; no uniform health gain follows from speed or conflicting air results.','traffic-air',sources=(1,),condition='Separate exposures, collisions and population incidence; do not count the same pollutant pathway twice.')

g=graph('sc-food-scraps','2023 residential and commercial throughput; earlier 2018 pilot not comparable','City of Santa Cruz participants; access varies by housing type','Municipal diverted-from-landfill accounting, not untreated comparison')
edge(g,'climate-change',T,I,'indirect','Landfill methane avoidance is plausible, but net CO2e is not measured by diverted tonnage.','organics-processing',magnitude=None,condition='Compare landfill methane capture with actual processing, transport and leakage; no automatic CO2e conversion.')
edge(g,'nitrogen-phosphorus-loading',U,I,'indirect','Recovered organics can recycle nutrients; actual nutrient losses or water-quality effects are unmeasured.','organics-nutrients',condition='Trace end use, fertilizer substitution, application rates and runoff.')
edge(g,'social-equity',M,O,'direct','2023 drop-off alternatives for unenrolled multifamily complexes show unequal convenience at that rollout stage.','organics-access',limit='Historical service access, not proof of present exclusion; current mandatory service spans housing types.')
edge(g,'food',U,I,'indirect','Food-scrap collection is not evidence of edible-food redistribution or reduced hunger.','organics-food',limit='Keep waste processing and food-access outcomes distinct.')
edge(g,'air-pollution',U,I,'indirect','Collection and processing can change truck and facility emissions; net local exposure is unmeasured.','organics-processing',condition='Measure routes, fleet and processing-site exposures.')

g=graph('nyc-paid-sick-leave','August 2011–July 2017','Continuously enrolled Medicaid adults 18–64; employment/leave receipt unobserved','NYC vs entropy-balanced adults elsewhere in New York State')
edge(g,'health',T,Q,'direct','Annual emergency-care probability falls in the study; not proof that all health outcomes improve.','sick-care',magnitude={'value':-0.6,'unit':'percentage points','metric':'Annual emergency-care probability','uncertainty':'95% CI −0.7 to −0.5; −0.6 points, not −0.6 percent'})
edge(g,'income-work',T,I,'direct','Paid leave can protect earnings during covered absences; actual employment and take-up were not observed in the study.','sick-income',sources=(1,),condition='Worker is eligible, knows the entitlement and can use it without retaliation.')
edge(g,'social-equity',M,I,'indirect','Potential protection depends on eligibility, job conditions and enforcement; distributional closure is unmeasured.','sick-income',condition='Examine access among low-wage and precarious workers rather than infer benefits to all Medicaid adults.')
edge(g,'gender-equality',U,I,'indirect','Care responsibilities may shape incidence, but gender-equity effects are not identified here.','sick-care',condition='Measure unpaid care and paid-leave use by gender without assuming equal exposure.')

g=graph('sc-community-choice-energy','2025 power label; distinct 2024 tariff illustration','3CE service portfolio and illustrative residential tariff customer','California utility-average total intensity; no causal no-CCA counterfactual')
edge(g,'climate-change',A,O,'direct','Reported total supplier intensity is higher than the comparable California utility-average total.','cca-accounting',magnitude={'value':551,'unit':'lbCO2e/MWh','metric':'3CE total vs California utility-average total 384','uncertainty':'Accounting comparison, not the causal effect of creating CCA'},limit='Away denotes higher pressure on this comparator, not historical deterioration, marginal emissions or a causal CCA failure.')
edge(g,'energy',T,MD,'direct','A matched-usage 2024 tariff example has a lower modeled bill; no measured energy-poverty outcome.','cca-bills',sources=(1,),magnitude={'value':-13.86,'unit':'USD/month at 375 kWh','metric':'Illustrative 3Cchoice vs PG&E E-TOU-C bill','uncertainty':'Different 2024 rate effective dates; not current rates or observed household savings'})
edge(g,'income-work',T,MD,'indirect','The same illustrative bill difference could free disposable income; it is not an independent second benefit.','cca-bills',sources=(1,),limit='Shared path with energy affordability. Do not add the same $13.86 twice.')
edge(g,'land-conversion',U,I,'indirect','New renewable procurement can affect offsite land use, but no attributable footprint is established here.','cca-procurement',sources=(2,),condition='Trace project additionality, siting and displaced supply.')

out={'schemaVersion':'1.0.0','asOf':d['asOf'],'directions':{'towardSafeJust':'Toward safe and just space on the stated outcome/comparator','away':'Away on the stated outcome/comparator','mixed':'Opposing effects, uneven incidence or conflicting findings; read edge','unknown':'Effect not established','noDemonstratedChange':'Tested outcome: change not demonstrated; not proof of zero'},'geometry':'Equal slices; arrows express direction only. Social improvement points outward from deprivation; ecological improvement points inward from overshoot. No arrow length, wedge area or color saturation represents magnitude.','deduplication':'pathId groups shared mechanisms. Never sum different native units or intermediate and final outcomes. No total score is computed.','graphs':graphs}
(root/'impact-graph.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n');(root/'impact-graph.js').write_text('window.POLICY_IMPACT_GRAPH = '+json.dumps(out,ensure_ascii=False)+';\n')
print(len(graphs),'policies;',sum(len(g['edges']) for g in graphs),'cross-slice edges')
